package ma.fstt.model;
import jakarta.persistence.*;
@Entity @Table(name="produit") public class Produit { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String nom; private String description; @Column(nullable=false) private double prix; @Column(nullable=false) private int stock; public Produit(){} public Produit(String n,String d,double p,int s){nom=n;description=d;prix=p;stock=s;} public Long getId(){return id;} public String getNom(){return nom;} public void setNom(String v){nom=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public double getPrix(){return prix;} public void setPrix(double v){prix=v;} public int getStock(){return stock;} public void setStock(int v){stock=v;} }